import styles from "../../styles.module.scss";
import React, { Component } from "react";
import Modal from "../Modal/Modal";
import { Link } from "react-router-dom";

class Right extends Component {
  constructor() {
    super();
    this.state = {
      imgIndex: null,
      modalOn: false,
    };
  }

  // 모달 토글
  test = (index) => {
    this.setState({
      imgIndex: index,
      modalOn: !this.state.modalOn,
    });
  };

  render() {
    const {
      content = [],
      keywords = [],
      folder = "",
      images = [],
      pdfs = [],
      title = "",
      subtitle = "",
    } = this.props;

    // keywords
    const keywordList = keywords.map((keyword, i) => (
      <span className={styles.keyword} key={i}>
        {keyword}
      </span>
    ));

    // content (tags)
    const tags = content.map((tag, i) => {
      if (tag?.sub?.length) {
        const subs = (
          <ul>
            {tag.sub.map((sub, j) => (
              <li key={j}>{sub}</li>
            ))}
          </ul>
        );

        return (
          <li key={i} className={styles.details}>
            <details>
              <summary>{tag.main}</summary>
              {subs}
            </details>
          </li>
        );
      }

      return <li key={i}>{tag.main}</li>;
    });

    // images
    const imageList = images.map((image, index) => (
      <img
        key={index}
        className={styles.ImageView}
        src={`projects/${folder}/${image}.png`}
        onClick={() => this.test(index)}
        alt=""
      />
    ));

    // pdfs
    const pdfList = pdfs.map((pdf, i) => (
      <Link key={i} to={`/pdfviewer/${folder}/${pdf}`} target="_blank">
        PDF GO
      </Link>
    ));

    return (
      <div className={styles.right}>
        <div>
          <h5>{title}</h5>
          <p>{subtitle}</p>
          <ul>{tags}</ul>
        </div>

        <div>{imageList}</div>

        <div>{keywordList}</div>

        <div>{pdfList}</div>

        {this.state.modalOn && (
          <Modal
            index={this.state.imgIndex}
            close={() => this.test(null)}
            images={images}
            title={title}
            subtitle={subtitle}
            folder={folder}
          />
        )}
      </div>
    );
  }
}

export default Right;
